export const GCODE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gcode-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGCodeStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GCODE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
